def parse_pairs(lines):
    result = {}
    for line in lines:
        if not line.strip():
            continue
        if '=' not in line:
            raise ValueError("Missing '='")
        key, value = line.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError("Empty key")
        result[key] = value
    return result

