def trim_history(messages, budget):
    if budget < 0:
        raise ValueError("Budget must be non-negative")

    for m in messages:
        if m['cost'] < 0:
            raise ValueError("Message cost must be non-negative")

    current_sum = 0
    suffix_start_index = len(messages)

    for i in range(len(messages) - 1, -1, -1):
        cost = messages[i]['cost']
        if current_sum + cost <= budget:
            current_sum += cost
            suffix_start_index = i
        else:
            break

    return messages[suffix_start_index:]

