def summarize_usage(events):
    request_max_input = {}
    request_max_output = {}

    for event in events:
        request_id = event['request_id']
        input_tokens = event.get('input', 0)
        output_tokens = event.get('output', 0)

        if input_tokens < 0 or output_tokens < 0:
            raise ValueError("Token counts must be non-negative")

        if request_id not in request_max_input:
            request_max_input[request_id] = 0
        if request_id not in request_max_output:
            request_max_output[request_id] = 0

        if input_tokens > request_max_input[request_id]:
            request_max_input[request_id] = input_tokens
        if output_tokens > request_max_output[request_id]:
            request_max_output[request_id] = output_tokens

    total_input = sum(request_max_input.values())
    total_output = sum(request_max_output.values())

    return {'input': total_input, 'output': total_output}

